import json
import re
import pandas as pd

def task_func(json_str):
    if not json_str:
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()

    if not isinstance(data, dict):
        return pd.DataFrame()

    number_pattern = re.compile(
        r"[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?"
    )

    def process_value(value):
        if isinstance(value, bool):
            return value

        if isinstance(value, (int, float)):
            return float(value) * 2.0

        if isinstance(value, str):
            stripped = value.strip()
            if number_pattern.fullmatch(stripped):
                try:
                    return float(stripped) * 2.0
                except (ValueError, OverflowError):
                    return value
            return value

        if isinstance(value, list):
            return [process_value(item) for item in value]

        return value

    normalized_data = {
        key: process_value(value)
        for key, value in data.items()
    }

    try:
        values = list(normalized_data.values())

        # A one-row DataFrame is needed when all values are scalar.
        if (
            normalized_data
            and all(not isinstance(value, (list, dict)) for value in values)
        ):
            return pd.DataFrame([normalized_data])

        return pd.DataFrame(normalized_data)
    except (ValueError, TypeError):
        return pd.DataFrame()


